package com.graduation.gateway.config;
import org.springframework.context.annotation.*; import org.springframework.core.convert.converter.Converter; import org.springframework.security.authentication.AbstractAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import reactor.core.publisher.Mono; import java.util.*;
@Configuration public class JwtRoleConverterConfig{ @Bean Converter<Jwt,Mono<AbstractAuthenticationToken>> jwtAuthenticationConverter(){ return jwt->{ String role=jwt.getClaimAsString("role"); var a=role==null?List.<SimpleGrantedAuthority>of():List.of(new SimpleGrantedAuthority("ROLE_"+role)); return Mono.just(new JwtAuthenticationToken(jwt,a,jwt.getSubject())); }; } }
